-- Local FAMILY and OWN-scope pgTAP proof. Only synthetic Auth users persist.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path = extensions, pg_catalog, public;
SELECT plan(41);
SELECT is((SELECT count(*) FROM auth.users WHERE email IN ('foundation-family-001@example.invalid','foundation-own-001@example.invalid','foundation-own-002@example.invalid')),3::bigint,'three dedicated local Auth users exist');
SELECT set_config('schoolos_test.family_subject',(SELECT id::text FROM auth.users WHERE email='foundation-family-001@example.invalid'),true);
SELECT set_config('schoolos_test.a_subject',(SELECT id::text FROM auth.users WHERE email='foundation-own-001@example.invalid'),true);
SELECT set_config('schoolos_test.b_subject',(SELECT id::text FROM auth.users WHERE email='foundation-own-002@example.invalid'),true);
SET ROLE schoolos_schema_owner;
