SELECT is((SELECT count(*) FROM app_private.principal_binding_events WHERE binding_id IN ('00000007-0000-4000-8000-000000000007','00000008-0000-4000-8000-000000000008','00000009-0000-4000-8000-000000000009') AND event_kind='BOUND'),3::bigint,'three binding history events generated by triggers');
SELECT is((SELECT count(*) FROM app_private.audit_events WHERE event_type='identity.binding_changed' AND target_ref IN ('00000007-0000-4000-8000-000000000007','00000008-0000-4000-8000-000000000008','00000009-0000-4000-8000-000000000009')),3::bigint,'three binding audit events generated by triggers');
SELECT throws_ok($sql$INSERT INTO app_private.principal_role_assignments(principal_id,principal_kind,role_id,role_family_only,context_kind,valid_from,created_by) VALUES('00000002-0000-4000-8000-000000000002','FAMILY','0000000b-0000-4000-8000-00000000000b',false,'FAMILY',statement_timestamp()-interval '1 hour','00000001-0000-4000-8000-000000000001')$sql$,'23514'::character(5),'new row for relation "principal_role_assignments" violates check constraint "principal_role_assignments_ck_02"','FAMILY cannot receive non-family staff role');
SELECT throws_ok($sql$INSERT INTO app_private.role_permission_grants(role_id,role_family_only,permission_id,permission_family_safe,valid_from,created_by) VALUES('0000000a-0000-4000-8000-00000000000a',true,'0000000f-0000-4000-8000-00000000000f',false,statement_timestamp()-interval '1 hour','00000001-0000-4000-8000-000000000001')$sql$,'23514'::character(5),'new row for relation "role_permission_grants" violates check constraint "role_permission_grants_ck_01"','family-only role cannot receive unsafe campus grant');
