INSERT INTO app.notification_preferences(id,principal_id,category_code,channel_code,enabled,created_by) VALUES('0000002a-0000-4000-8000-00000000002a','00000005-0000-4000-8000-000000000005','FOUNDATION_TEST','IN_APP',true,'00000001-0000-4000-8000-000000000001'),('0000002b-0000-4000-8000-00000000002b','00000006-0000-4000-8000-000000000006','FOUNDATION_TEST','IN_APP',true,'00000001-0000-4000-8000-000000000001');
RESET ROLE;
SELECT set_config('schoolos_test.family_cutoff',(SELECT extract(epoch FROM tokens_valid_from)::bigint::text FROM app_private.principal_auth_bindings WHERE id='00000007-0000-4000-8000-000000000007'),true);
SELECT set_config('schoolos_test.a_cutoff',(SELECT extract(epoch FROM tokens_valid_from)::bigint::text FROM app_private.principal_auth_bindings WHERE id='00000008-0000-4000-8000-000000000008'),true);
SELECT set_config('schoolos_test.b_cutoff',(SELECT extract(epoch FROM tokens_valid_from)::bigint::text FROM app_private.principal_auth_bindings WHERE id='00000009-0000-4000-8000-000000000009'),true);
-- FAMILY has a complete family-safe OWN inbox chain. An unrelated staff campus chain exists.
SELECT set_config('request.jwt.claim.sub',current_setting('schoolos_test.family_subject'),true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('schoolos_test.family_subject'),'role','authenticated','iat',current_setting('schoolos_test.family_cutoff')::bigint,'is_anonymous',false)::text,true);
SET ROLE authenticated;
SELECT is((SELECT count(*) FROM app.notifications WHERE id='00000027-0000-4000-8000-000000000027'),1::bigint,'FAMILY reads its own family-safe notification');
SELECT is((SELECT count(*) FROM app.notifications WHERE id='00000028-0000-4000-8000-000000000028'),0::bigint,'FAMILY cannot read A notification');
SELECT is((SELECT count(*) FROM app.campuses WHERE id='00000023-0000-4000-8000-000000000023'),0::bigint,'FAMILY cannot mix into staff Campus grant');
RESET ROLE;
SELECT is((SELECT count(*) FROM app_private.principal_role_assignments WHERE id='00000015-0000-4000-8000-000000000015' AND role_id='0000000a-0000-4000-8000-00000000000a'),1::bigint,'FAMILY assignment is a family-only role');
SELECT is((SELECT count(*) FROM app_private.role_permission_grants WHERE id='00000014-0000-4000-8000-000000000014' AND role_id='0000000b-0000-4000-8000-00000000000b'),1::bigint,'unrelated live staff Campus grant exists');
SELECT set_config('request.jwt.claim.sub',current_setting('schoolos_test.a_subject'),true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('schoolos_test.a_subject'),'role','authenticated','iat',current_setting('schoolos_test.a_cutoff')::bigint,'is_anonymous',false)::text,true);
SET ROLE authenticated;
SELECT is((SELECT count(*) FROM app.campuses WHERE id='00000023-0000-4000-8000-000000000023'),1::bigint,'A staff chain really reads Campus A');
SELECT is((SELECT count(*) FROM app.notifications WHERE id='00000028-0000-4000-8000-000000000028'),1::bigint,'A reads own notification');
SELECT is((SELECT count(*) FROM app.notifications WHERE id='00000029-0000-4000-8000-000000000029'),0::bigint,'A cannot read B notification');
SELECT is((SELECT count(*) FROM app.notifications WHERE id IN ('00000028-0000-4000-8000-000000000028','00000029-0000-4000-8000-000000000029')),1::bigint,'two-notification query exposes only A');
SELECT is((SELECT count(*) FROM app.notification_preferences WHERE id='0000002a-0000-4000-8000-00000000002a'),1::bigint,'A reads own preference');
SELECT is((SELECT count(*) FROM app.notification_preferences WHERE id='0000002b-0000-4000-8000-00000000002b'),0::bigint,'A cannot read B preference');
SELECT is((SELECT count(*) FROM app.notification_preferences WHERE id IN ('0000002a-0000-4000-8000-00000000002a','0000002b-0000-4000-8000-00000000002b')),1::bigint,'two-preference query exposes only A');
SELECT is((SELECT count(*) FROM app.read_own_principal()),1::bigint,'A self grant returns one checked projection');
SELECT is((SELECT principal_id FROM app.read_own_principal()),'00000005-0000-4000-8000-000000000005'::uuid,'A projection identifies A, never B');
SELECT is((SELECT principal_kind || ':' || display_label FROM app.read_own_principal()),'INDIVIDUAL:Principal A','A projection has only reviewed kind and label');
RESET ROLE;
-- notification grant removed: savepoint restores the complete base chain after observing RLS.
SAVEPOINT case_state;
SET ROLE schoolos_schema_owner;
UPDATE app_private.role_permission_grants SET revoked_at=clock_timestamp() WHERE id='00000011-0000-4000-8000-000000000011';
RESET ROLE;
SET ROLE authenticated;
SELECT (SELECT count(*)::bigint FROM app.notifications WHERE id='00000028-0000-4000-8000-000000000028') AS n_removed \gset
RESET ROLE;
ROLLBACK TO SAVEPOINT case_state;
SELECT is(:'n_removed'::bigint,0::bigint,'revoked notification grant hides A inbox');

-- preference scope removed: savepoint restores the complete base chain after observing RLS.
SAVEPOINT case_state;
SET ROLE schoolos_schema_owner;
UPDATE app_private.assignment_permission_scopes SET revoked_at=clock_timestamp() WHERE id='0000001e-0000-4000-8000-00000000001e';
RESET ROLE;
SET ROLE authenticated;
SELECT (SELECT count(*)::bigint FROM app.notification_preferences WHERE id='0000002a-0000-4000-8000-00000000002a') AS p_removed \gset
RESET ROLE;
ROLLBACK TO SAVEPOINT case_state;
SELECT is(:'p_removed'::bigint,0::bigint,'revoked preference scope hides A preference');

-- self grant removed: savepoint restores the complete base chain after observing RLS.
SAVEPOINT case_state;
SET ROLE schoolos_schema_owner;
UPDATE app_private.role_permission_grants SET revoked_at=clock_timestamp() WHERE id='00000013-0000-4000-8000-000000000013';
RESET ROLE;
SET ROLE authenticated;
SELECT (SELECT count(*)::bigint FROM app.read_own_principal()) AS s_removed \gset
RESET ROLE;
ROLLBACK TO SAVEPOINT case_state;
SELECT is(:'s_removed'::bigint,0::bigint,'revoked principal self grant hides A projection');

SELECT set_config('request.jwt.claim.sub',current_setting('schoolos_test.b_subject'),true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('schoolos_test.b_subject'),'role','authenticated','iat',current_setting('schoolos_test.b_cutoff')::bigint,'is_anonymous',false)::text,true);
SET ROLE authenticated;
SELECT is((SELECT count(*) FROM app.read_own_principal()),0::bigint,'B has no self scope and receives no projection');
RESET ROLE;
SET ROLE schoolos_schema_owner;
INSERT INTO app_private.assignment_permission_scopes(id,assignment_id,grant_id,role_id,permission_id,scope_contract_id,scope_kind,resolver_key,campus_id,valid_from,created_by) VALUES('00000020-0000-4000-8000-000000000020','00000017-0000-4000-8000-000000000017','00000013-0000-4000-8000-000000000013','0000000b-0000-4000-8000-00000000000b','0000000e-0000-4000-8000-00000000000e','0000001a-0000-4000-8000-00000000001a','OWN','SELF_PRINCIPAL',NULL,statement_timestamp()-interval '1 hour','00000001-0000-4000-8000-000000000001');
RESET ROLE;
SET ROLE authenticated;
SELECT is((SELECT principal_id FROM app.read_own_principal()),'00000006-0000-4000-8000-000000000006'::uuid,'B complete own chain returns B');
SELECT is((SELECT count(*) FROM app.read_own_principal() WHERE principal_id='00000005-0000-4000-8000-000000000005'),0::bigint,'B projection excludes A');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub',current_setting('schoolos_test.a_subject'),true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('schoolos_test.a_subject'),'role','authenticated','iat',current_setting('schoolos_test.a_cutoff')::bigint,'is_anonymous',false)::text,true);
SET ROLE authenticated;
SELECT is((SELECT principal_id FROM app.read_own_principal()),'00000005-0000-4000-8000-000000000005'::uuid,'A remains A despite B live own authority');
SELECT is((SELECT count(*) FROM app.notifications WHERE id='00000029-0000-4000-8000-000000000029'),0::bigint,'A cannot read B inbox despite B own authority');
RESET ROLE;
-- stale A token: savepoint restores the complete base chain after observing RLS.
SAVEPOINT case_state;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('schoolos_test.a_subject'),'role','authenticated','iat',current_setting('schoolos_test.a_cutoff')::bigint-1,'is_anonymous',false)::text,true);
SET ROLE authenticated;
SELECT (SELECT count(*)::bigint FROM app.notifications WHERE id='00000028-0000-4000-8000-000000000028') AS stale_n \gset
SELECT (SELECT count(*)::bigint FROM app.read_own_principal()) AS stale_s \gset
RESET ROLE;
ROLLBACK TO SAVEPOINT case_state;
SELECT is(:'stale_n'::bigint,0::bigint,'stale A token hides own notification');
SELECT is(:'stale_s'::bigint,0::bigint,'stale A token hides own projection');

SET ROLE authenticated;
SELECT is((SELECT count(*) FROM app.notifications WHERE id='00000028-0000-4000-8000-000000000028'),1::bigint,'iat at actual A cutoff restores own inbox');
SELECT is((SELECT count(*) FROM app.read_own_principal()),1::bigint,'iat at actual A cutoff restores own projection');
RESET ROLE;
-- SUSPENDED A: savepoint restores the complete base chain after observing RLS.
SAVEPOINT case_state;
SET ROLE schoolos_schema_owner;
UPDATE app_private.principals SET state='SUSPENDED' WHERE id='00000005-0000-4000-8000-000000000005';
RESET ROLE;
SET ROLE authenticated;
SELECT (SELECT count(*)::bigint FROM app.notifications WHERE id='00000028-0000-4000-8000-000000000028') AS suspended_n \gset
SELECT (SELECT count(*)::bigint FROM app.notification_preferences WHERE id='0000002a-0000-4000-8000-00000000002a') AS suspended_p \gset
SELECT (SELECT count(*)::bigint FROM app.read_own_principal()) AS suspended_s \gset
RESET ROLE;
ROLLBACK TO SAVEPOINT case_state;
SELECT is(:'suspended_n'::bigint,0::bigint,'SUSPENDED A cannot read own notification');
SELECT is(:'suspended_p'::bigint,0::bigint,'SUSPENDED A cannot read own preference');
SELECT is(:'suspended_s'::bigint,0::bigint,'SUSPENDED A cannot read own projection');

-- RETIRED A: savepoint restores the complete base chain after observing RLS.
SAVEPOINT case_state;
SET ROLE schoolos_schema_owner;
UPDATE app_private.principals SET state='RETIRED' WHERE id='00000005-0000-4000-8000-000000000005';
RESET ROLE;
SET ROLE authenticated;
SELECT (SELECT count(*)::bigint FROM app.notifications WHERE id='00000028-0000-4000-8000-000000000028') AS retired_n \gset
SELECT (SELECT count(*)::bigint FROM app.notification_preferences WHERE id='0000002a-0000-4000-8000-00000000002a') AS retired_p \gset
SELECT (SELECT count(*)::bigint FROM app.read_own_principal()) AS retired_s \gset
RESET ROLE;
ROLLBACK TO SAVEPOINT case_state;
SELECT is(:'retired_n'::bigint,0::bigint,'RETIRED A cannot read own notification');
SELECT is(:'retired_p'::bigint,0::bigint,'RETIRED A cannot read own preference');
SELECT is(:'retired_s'::bigint,0::bigint,'RETIRED A cannot read own projection');

SET ROLE authenticated;
SELECT is((SELECT count(*) FROM pg_class t JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname IN ('app','app_private') AND t.relkind='r' AND has_any_column_privilege(current_user,t.oid,'SELECT')),5::bigint,'authenticated retains exactly five reviewed table read surfaces');
SELECT ok(NOT has_any_column_privilege(current_user,'app_private.principals','SELECT') AND NOT has_any_column_privilege(current_user,'app_private.principal_auth_bindings','SELECT') AND NOT has_any_column_privilege(current_user,'app_private.roles','SELECT') AND NOT has_any_column_privilege(current_user,'app_private.permissions','SELECT') AND NOT has_any_column_privilege(current_user,'app_private.role_permission_grants','SELECT') AND NOT has_any_column_privilege(current_user,'app_private.principal_role_assignments','SELECT') AND NOT has_any_column_privilege(current_user,'app_private.permission_scope_contracts','SELECT') AND NOT has_any_column_privilege(current_user,'app_private.assignment_permission_scopes','SELECT'),'authenticated cannot directly SELECT private identity or RBAC inputs');
SELECT ok(NOT has_function_privilege(current_user,'app_private.current_principal_id()','EXECUTE') AND NOT has_function_privilege(current_user,'app_private.has_complete_grant(text,text,uuid)','EXECUTE'),'authenticated cannot directly execute internal helpers');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
